def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def require(condition: bool, message: str) -> None:
    if not condition:
        raise RuntimeError(message)


def payload(spec: dict[str, Any], kind: str) -> bytes:
    data = zlib.decompress(base64.b85decode(spec[f"{kind}_payload"]))
    require(sha(data) == spec[f"{kind}_sha256"], f"embedded {kind} SHA mismatch")
    return data


def request_json(path: str, timeout: float = 30) -> tuple[int, Any]:
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    try:
        with opener.open(BASE_URL + path, timeout=timeout) as response:
            raw = response.read().decode("utf-8", errors="replace")
            return response.status, json.loads(raw) if raw else {}
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode("utf-8", errors="replace")
        try:
            return exc.code, json.loads(raw)
        except Exception:
            return exc.code, {"raw": raw}


def run(command: list[str], timeout: float) -> subprocess.CompletedProcess[str]:
    result = subprocess.run(command, text=True, capture_output=True, timeout=timeout, check=False)
    if result.returncode != 0:
        raise RuntimeError(
            f"command failed ({result.returncode}): {command!r}\n"
            f"stdout:\n{result.stdout[-3000:]}\nstderr:\n{result.stderr[-3000:]}"
        )
    return result


def port_open(port: int) -> bool:
    try:
        with socket.create_connection(("127.0.0.1", port), timeout=1):
            return True
    except OSError:
        return False


def projects() -> list[str]:
    status, body = request_json("/api/director/projects")
    require(status == 200 and isinstance(body, list), "baseline project list unavailable")
    return [
        str(item.get("project_id") or item.get("id") or "").strip()
        for item in body
        if isinstance(item, dict)
        and str(item.get("project_id") or item.get("id") or "").strip()
    ]


def check_active_tasks() -> None:
    for project_id in projects():
        status, body = request_json(
            f"/api/studio/projects/{project_id}/stage04/rebuild-production/status"
        )
        require(status == 200, f"cannot inspect Stage04 task: {project_id}")
        task_status = str((body or {}).get("status") or "")
        require(
            task_status not in {"queued", "running"},
            f"refusing install: Stage04 task active for {project_id}: {task_status}",
        )


def atomic_write(path: Path, data: bytes, mode: int) -> None:
    temp = path.with_name(path.name + ".v23962.tmp")
    temp.write_bytes(data)
    os.chmod(temp, mode)
    temp.replace(path)


def stop_platform() -> None:
    run(["bash", str(ROOT / "scripts" / "stop.sh")], 60)
    deadline = time.monotonic() + 20
    while port_open(6008) and time.monotonic() < deadline:
        time.sleep(1)
    require(not port_open(6008), "port 6008 is still listening after stop")


def start_platform() -> None:
    run(["bash", str(ROOT / "scripts" / "start.sh")], 120)
    deadline = time.monotonic() + 90
    last = ""
    while time.monotonic() < deadline:
        try:
            status, body = request_json("/api/health", timeout=30)
            if status == 200:
                require(body.get("version") == TARGET_VERSION, "health version mismatch")
                status, schema = request_json("/openapi.json", timeout=15)
                require(status == 200, "OpenAPI unavailable")
                require(schema.get("info", {}).get("version") == TARGET_VERSION, "OpenAPI version mismatch")
                return
            last = f"HTTP {status}: {body}"
        except Exception as exc:
            last = str(exc)
        time.sleep(2)
    raise RuntimeError(f"platform health timeout: {last}")


def self_test() -> int:
    for rel, spec in FILES.items():
        baseline = payload(spec, "baseline")
        target = payload(spec, "target")
        require(baseline != target, f"target unexpectedly equals baseline: {rel}")
        ast.parse(baseline.decode("utf-8"), filename=rel)
        ast.parse(target.decode("utf-8"), filename=rel)
    runtime = payload(FILES["app/stage04_v238_runtime.py"], "target").decode("utf-8")
    main = payload(FILES["app/main.py"], "target").decode("utf-8")
    for marker in (
        "_merge_shot_repair_patch",
        "_missing_shot_state_fields",
        "V2.39.10.7_SHOT_CONTEXT_COMPACTION",
        "forward_with_replayed_prefix",
        "await _scene_global_audit",
    ):
        require(marker in runtime, f"target runtime guard missing: {marker}")
    for marker in ("_studio_v23962_close_validated_beats", "_studio_v23962_audit_beats", "SUPERCHUNK_NARRATIVE_AUDIT"):
        require(marker in main, f"target main lineage guard missing: {marker}")
    require(TARGET_VERSION in runtime and TARGET_VERSION in main, "target version missing")
    for rel, spec in FILES.items():
        compile(payload(spec, "target"), rel, "exec")
    print("INSTALLER SELF-TEST PASS")
    return 0


def main() -> int:
    if "--self-test" in sys.argv:
        return self_test()

    require(ROOT.is_dir(), f"platform root missing: {ROOT}")
    require(PYTHON.is_file(), f"platform Python missing: {PYTHON}")
    status, schema = request_json("/openapi.json")
    require(status == 200, "baseline platform 6008 is not reachable")
    require(schema.get("info", {}).get("version") == BASELINE_VERSION, "baseline OpenAPI version mismatch")
    check_active_tasks()

    before: dict[str, bytes] = {}
    modes: dict[str, int] = {}
    for rel, spec in FILES.items():
        path = ROOT / rel
        require(path.is_file(), f"baseline file missing: {rel}")
        live = path.read_bytes()
        baseline = payload(spec, "baseline")
        require(live == baseline, f"baseline payload mismatch: {rel}")
        require(sha(live) == spec["baseline_sha256"], f"baseline SHA256 mismatch: {rel}")
        before[rel] = live
        modes[rel] = os.stat(path).st_mode & 0o777

    backup = Path("/root/autodl-tmp/ai-studio/backups") / (
        "platform-v2-v23962-" + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    )
    backup.mkdir(parents=True, exist_ok=False)
    for rel, data in before.items():
        destination = backup / rel
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_bytes(data)
        os.chmod(destination, modes[rel])

    manifest = {
        "baseline_version": BASELINE_VERSION,
        "target_version": TARGET_VERSION,
        "created_at": datetime.now(timezone.utc).isoformat(),
        "files": {
            rel: {
                "before_sha256": sha(data),
                "target_sha256": FILES[rel]["target_sha256"],
                "mode": modes[rel],
            }
            for rel, data in before.items()
        },
    }
    (backup / "manifest.json").write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )

    applied = False
    try:
        applied = True
        stop_platform()
        for rel, spec in FILES.items():
            atomic_write(ROOT / rel, payload(spec, "target"), modes[rel])

        run(
            [
                str(PYTHON), "-m", "py_compile",
                str(ROOT / "app" / "main.py"),
                str(ROOT / "app" / "stage04_v238_runtime.py"),
            ],
            180,
        )
        start_platform()

        for rel, spec in FILES.items():
            require(
                sha((ROOT / rel).read_bytes()) == spec["target_sha256"],
                f"live target readback mismatch: {rel}",
            )
        runtime_source = (ROOT / "app" / "stage04_v238_runtime.py").read_text(encoding="utf-8")
        for marker in (
            "_merge_shot_repair_patch",
            "V2.39.10.7_SHOT_CONTEXT_COMPACTION",
            "forward_with_replayed_prefix",
            "await _scene_global_audit",
        ):
            require(marker in runtime_source, f"live semantic guard missing: {marker}")

        manifest["completed_at"] = datetime.now(timezone.utc).isoformat()
        manifest["result"] = "INSTALLED"
        (backup / "manifest.json").write_text(
            json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
        )
        print(json.dumps(manifest, ensure_ascii=False, indent=2))
        print(f"BACKUP={backup}")
        print("INSTALL PASS; no Stage04 rebuild, image or video task was executed")
        return 0
    except Exception:
        if applied:
            try:
                if port_open(6008):
                    stop_platform()
            except Exception as stop_exc:
                print(f"ROLLBACK STOP WARNING: {stop_exc}", file=sys.stderr)
            for rel, spec in FILES.items():
                atomic_write(ROOT / rel, payload(spec, "baseline"), modes[rel])
                require(
                    sha((ROOT / rel).read_bytes()) == spec["baseline_sha256"],
                    f"rollback readback mismatch: {rel}",
                )
            try:
                run(["bash", str(ROOT / "scripts" / "start.sh")], 120)
            except Exception as restart_exc:
                print(f"ROLLBACK RESTORED FILES BUT RESTART FAILED: {restart_exc}", file=sys.stderr)
            print(f"ROLLBACK COMPLETE FROM {backup}", file=sys.stderr)
        raise


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f"INSTALL FAIL: {type(exc).__name__}: {exc}", file=sys.stderr)
        raise
